from h import *
R(9361657,"فطيرة الليمون الأخضر (كي لايم) النباتية",
"فطيرة الليمون الأخضر النباتية هذه حامضة بإتقان وسهلة التحضير! تُحضَّر في 15 دقيقة أو أقل. فقط اخلط واسكب وجمّد!",
"8 شرائح","حصة واحدة",
["1 قاعدة فطيرة نباتية من القمح الكامل أو قاعدة من اختيارك","300 جرام توفو طري، غير معدل وراثيًا إن أمكن","½ كوب كاجو نيء","1 حبة أفوكادو ناضجة مقشّرة ومنزوعة النواة","½-¾ كوب عصير ليمون أخضر، أي حوالي 2-3 ليمونات خضراء كبيرة أو 4-5 صغيرة (بحسب درجة الحموضة التي تفضلها، ونحن نفضل ¾ كوب)","⅓ كوب سكر أبيض ناعم، واستخدم سكر جوز الهند أو سكر التمر لخيار سكر غير مكرر","½ ملعقة صغيرة زنجبيل مطحون، اختياري","شرائح ليمون أخضر وقشر ليمون أخضر مبشور وجوز هند مبشور"],
["حضّر قاعدة الفطيرة التي اخترتها واخبزها بدون حشوة حسب تعليماتها. إذا كنت تستخدم قاعدة الفطيرة الخالية من الزيت الخاصة بي، فاخبزها لمدة 15-20 دقيقة حتى تصبح الحواف ذهبية. ضعها جانبًا لتبرد قبل الحشو.","ضع جميع مكونات الحشوة في الخلاط واخلطها حتى تصبح ناعمة. ثم اسكب الخليط في القاعدة وافرده بأكبر قدر ممكن من التساوي.","جمّدها طوال الليل، أو لمدة 4-6 ساعات على الأقل. وبعد التجميد، اتركها في درجة حرارة الغرفة لمدة 5-10 دقائق ليسهل تقطيعها، ثم زيّنها وقدّمها."],
["إذا لم يكن لديك خلاط عالي السرعة، فانقع الكاجو في ماء ساخن لمدة 30 دقيقة ثم صفّه قبل خلطه مع بقية المكونات. سيساعد ذلك على تليينه مما يسهّل خلطه. احرص على التخطيط مسبقًا، فطعم هذه الفطيرة أفضل عندما تُجمَّد لمدة 4-6 ساعات على الأقل. هذه الفطيرة حامضة أكثر منها حلوة. إذا كنت تفضل فطيرة أحلى، فزد السكر إلى نصف كوب، مع العلم أن ذلك سيزيد السعرات الحرارية أيضًا. وإذا كنت تفضلها شديدة الحموضة، فاستخدم ما يصل إلى ¾ كوب من عصير الليمون الأخضر الطازج. ويمكنك أيضًا إضافة 1-2 ملعقة صغيرة من قشر الليمون الأخضر المبشور لمزيد من الحيوية. المعلومات الغذائية لشريحة واحدة (أو ⅛) من الفطيرة، بما في ذلك قاعدة الفطيرة الخالية من الزيت الخاصة بي. وإذا كنت تستخدم قاعدة أخرى، فستختلف المعلومات الغذائية."],
{"Optional Garnishes":"للتزيين (اختياري)"})
R(9367621,"شوربة العدس والبازلاء المجففة في Instant Pot [أو على الموقد]",
"تُحضَّر شوربة العدس والبازلاء المجففة في قدر واحد، في Instant Pot أو على الموقد. إنها مشبعة وغنية بالعناصر الغذائية ولذيذة بشكل لا يصدق. تحضير بسيط وتجهز في لمح البصر!",
"6 حصص","حصة واحدة",
["1 حبة بصل أصفر مقطعة مكعبات","2 حبة جزر مقشّرة ومقطعة مكعبات","2 عود كرفس مقطع مكعبات","6-8 أكواب مرق خضار قليل الصوديوم *انظر الملاحظات","1 كوب بازلاء مجففة مقسومة صفراء أو خضراء","1 كوب عدس أخضر أو بني","½ كوب بازلاء مجمدة","½ كوب ذرة مجمدة","1 ملعقة صغيرة مسحوق الثوم","½ ملعقة صغيرة كمون","ملح + فلفل حسب الرغبة"],
["أضف بضع ملاعق كبيرة من الماء أو المرق إلى قدرك مع البصل والجزر والكرفس. قلّب حتى تلين، حوالي 5 دقائق.","أضف جميع المكونات المتبقية وأوصلها إلى الغليان. ثم اخفض الحرارة ودعها تغلي على نار هادئة والغطاء على القدر ولكن مائلًا قليلًا لمدة 25-30 دقيقة. تذوّق وعدّل الملح والفلفل إن رغبت، وقدّم.","أضف بضع ملاعق كبيرة من الماء أو المرق إلى قدرك مع البصل والجزر والكرفس. قلّب حتى تلين، حوالي 5 دقائق.","أضف جميع المكونات المتبقية وأغلق الغطاء وضع الصمام في وضع الإغلاق. اضبطه على ضغط عالٍ لمدة 8 دقائق. (سيستغرق بناء الضغط حوالي 15 دقيقة قبل أن يبدأ المؤقت بالعد التنازلي.) ثم أطلق الضغط بسرعة وافتح الغطاء عندما يكون ذلك آمنًا، وقدّمها مع مزيد من الملح والفلفل عند الحاجة."],
["بحسب القوام الذي تفضله، استخدم ما بين 6-8 أكواب من مرق الخضار. للحصول على شوربة أكثر كثافة، استخدم ستة أكواب. وللحصول على شوربة أخف، استخدم ثمانية. تذكّر أن الشوربة ستمتص مزيدًا من السائل عندما تبرد.","استخدم مرق خضار قليل الصوديوم. فيمكنك دائمًا إضافة مزيد من الملح عند الحاجة، لكن لا يمكنك إزالته.","إذا لم يكن لديك مرق قليل الصوديوم، فاستخدم نصف مرق ونصف ماء. وبعد الطهي، تذوّق وأضف مزيدًا من الملح عند الحاجة.","أو، إذا لم يكن لديك أي مرق في المنزل، فيمكنك تحضير مرق بوصفة المكعبات المركزة السهلة هذه. (أنصح بشدة بهذا المرق لنكهته الرائعة.)","يبقى المتبقي صالحًا في الثلاجة لمدة تصل إلى 4 أيام أو يُجمَّد في وعاء محكم الإغلاق لمدة تصل إلى 3 أشهر."],
{"Stove Top Directions":"طريقة التحضير على الموقد","Instant Pot Directions":"طريقة التحضير في Instant Pot"})
R(9368018,"كوكيز القرع ورقائق الشوكولاتة النباتية",
"كوكيز القرع ورقائق الشوكولاتة الغني والحلو والمدلل! إنه صحي بشكل خفي، لكنه لذيذ جدًا لدرجة أنك لن تخمّن ذلك!",
"26 قطعة كوكيز","حصة واحدة",
["¾ كوب هريس القرع (وليس حشوة فطيرة القرع)","¼ كوب شراب القيقب","¼ كوب دبس السكر الفاخر أو مزيد من شراب القيقب إن أردت","¼ كوب طحينة أو زبدة الكاجو أو اللوز الكريمية","220 جرامًا من دقيق الشوفان، خالٍ من الغلوتين إن أردت (حوالي 2 كوب)","1 ملعقة كبيرة قرفة","¼ ملعقة صغيرة جوزة الطيب","½ ملعقة صغيرة بيكربونات الصوديوم","⅓ كوب رقائق شوكولاتة نباتية أو أكثر"],
["سخّن الفرن مسبقًا على 350 درجة فهرنهايت (175 درجة مئوية) وبطّن صينية خبز كبيرة بورق الزبدة. (استخدم صينيتين إذا كانتا أصغر.)","ضع المكونات السائلة في وعاء كبير واخلطها جيدًا. ثم أضف المكونات الجافة إلى الوعاء نفسه وقلّب حتى تمتزج. وأخيرًا، أضف رقائق الشوكولاتة بالتحريك الرفيع من الأسفل إلى الأعلى.","استخدم مغرفة كوكيز لتقسيم العجين إلى حوالي 26 قطعة كوكيز على صينية أو صينيتي الخبز. ثم استخدم ملعقة أو أصابع مبللة للضغط برفق على كل قطعة وتشكيلها على هيئة دوائر، فهي لا تنتشر كثيرًا أثناء الخَبز. اجعل سمكها حوالي ¼ بوصة. ثم، إن أردت، اضغط بضع رقائق شوكولاتة إضافية على سطح كل قطعة.","اخبزها لمدة 10-11 دقيقة ثم أخرجها من الفرن. قد تبدو غير ناضجة تمامًا، لكنها ستتماسك أكثر عندما تبرد. اتركها لتبرد 5-10 دقائق قبل نقلها واستمتع بها."],
["زِن الدقيق باستخدام ميزان المطبخ إن أمكن. فهذا يعطي أفضل النتائج. استخدام كمية قليلة جدًا أو كثيرة جدًا من الدقيق سيغيّر قوام الكوكيز. إذا لم يكن لديك ميزان مطبخ، فقس 2 كوب من الدقيق، لكن لا تغترفه من الكيس. اسكبه بالملعقة في كوب القياس وسوِّ سطحه بسكين. لا ينتشر كوكيز القرع هذا كثيرًا، لذا استخدم يدين/أصابع مبللة قليلًا (لمنع الالتصاق) للضغط عليه وتشكيله على هيئة دوائر قبل الخَبز. اضغط برفق بضع رقائق شوكولاتة إضافية على سطح كل قطعة كوكيز قبل الخَبز للحصول على أقصى درجات الطراوة اللذيذة. قد يبدو الكوكيز غير ناضج تمامًا عند 10-11 دقيقة، لكن أخرجه من الفرن على أي حال لأنه سيتماسك أكثر عندما يبرد. لا تُفرط في الخَبز وإلا جفّ. اترك الكوكيز ليبرد 5-10 دقائق قبل نقله من صينية الخبز. فالكوكيز الساخن قد ينكسر بسهولة، لذا ابتعد قليلًا إن لزم الأمر. 😉 يبقى المتبقي صالحًا في وعاء محكم الإغلاق في درجة حرارة الغرفة لمدة 3-4 أيام. ويمكنك حفظه في الثلاجة لمدة تصل إلى أسبوع أو تجميده في وعاء محكم الإغلاق مناسب للتجميد لمدة تصل إلى 3 أشهر. تأكد من أنه بارد تمامًا إلى درجة حرارة الغرفة قبل التجميد."],
{"Wet Ingredient":"المكونات السائلة","Dry Ingredients":"المكونات الجافة","Fill In":"الإضافات"})
R(9368185,"كوكيز الشوفان والتوت البري النباتي [خالٍ من الزيت]",
"كوكيز الشوفان والتوت البري النباتي المطاطي واللذيذ بشكل لا يصدق صحي بما يكفي للفطور، ولذيذ بما يكفي للحلوى، ووجبة خفيفة مثالية في منتصف النهار.",
"14 قطعة كوكيز","حصة واحدة",
["2 كوب شوفان مجروش وليس سريع التحضير","½ كوب توت بري مجفف غير محلى","⅓ كوب بذور قرع مقشّرة","1 ملعقة كبيرة قرفة","½ ملعقة صغيرة ملح البحر","¾ كوب موز مهروس، أي حوالي موزتين كبيرتين ناضجتين","½ كوب صلصة التفاح غير المحلاة","2 ملعقة كبيرة شراب القيقب"],
["سخّن الفرن مسبقًا على 350 درجة وبطّن صينية خبز كبيرة بورق الزبدة.","اهرس الموز في وعاء خلط كبير، ثم أضف صلصة التفاح وشراب القيقب. اخلط جيدًا. ثم أضف جميع المكونات الجافة وقلّب حتى تتغطى بالتساوي.","استخدم مغرفة كوكيز متوسطة واضغط الخليط في المغرفة قبل إفراغه على الصينية. أنت تريد الضغط عليه في المغرفة للتأكد من عدم وجود فراغات ولمنع تفتته. كرر العملية مع بقية الخليط، وستحصل على حوالي 14 قطعة كوكيز.","اخبز لمدة 13-18 دقيقة. أخرجه من الفرن واتركه ليبرد 5-10 دقائق ليتماسك تمامًا. للحصول على كوكيز أطرى وأكثر مطاطية، اخبزه لمدة 13-14 دقيقة، أما للحصول على كوكيز أكثر قرمشة، فاخبزه لمدة 17-18 دقيقة."],
["استخدم موزًا ناضجًا جدًا. فالموز ذو القشر البني هو الأنسب هنا لإضافة حلاوة طبيعية لأننا لا نستخدم كمية كبيرة من السكر للتحلية. استخدم مغرفة كوكيز متوسطة للحصول على قطع كوكيز متساوية الحجم، أو مغرفة آيس كريم إذا لم تكن لديك. اضغط الخليط بقوة في المغرفة قبل إفراغه على الصينية. سيساعد ذلك على منع الفراغات في الكوكيز ليتماسك جيدًا. للحصول على كوكيز أطرى وأكثر رطوبة، اخبزه لمدة 13-14 دقيقة وأخرجه من الفرن لكن اتركه ليتماسك في درجة حرارة الغرفة لمدة 5 دقائق على الأقل قبل الاستمتاع به. وللحصول على قوام أكثر قرمشة، اخبزه لمدة 17-18 دقيقة. احرص على استخدام شوفان معتمد خالٍ من الغلوتين عند الحاجة. يبقى الكوكيز صالحًا لمدة 3-4 أيام في درجة حرارة الغرفة، وأسبوع في الثلاجة، و3 أشهر في الفريزر."],
{"Dry Ingredients":"المكونات الجافة","Wet Ingredients":"المكونات السائلة"})
R(9373142,"كاتشو إي بيبي النباتية",
"لمسة راقية على المعكرونة بالجبن تقدم لك طبقًا إيطاليًا كلاسيكيًا بنسخة نباتية بالطبع. ;)",
"4 حصص","حصة واحدة",
["½ رطل سباغيتي (أو بوكاتيني)","½ كوب كاجو","⅓ كوب خميرة غذائية","½ ملعقة صغيرة ملح البحر","½ ملعقة صغيرة حبوب فلفل أسود (أو فلفل أسود مطحون)","¼ ملعقة صغيرة مسحوق الثوم","2 ملعقة كبيرة عصير ليمون (حوالي نصف ليمونة)","⅓ كوب ماء عذب"],
["اغلِ قدرًا من الماء المملح بسخاء واسلق المعكرونة حسب تعليمات العبوة للحصول على معكرونة \"الدنتي\". عند نضجها، احتفظ بنصف كوب من ماء المعكرونة، وصفِّ الباقي وأعدها إلى القدر.","في هذه الأثناء، ضع جميع مكونات الصلصة في الخلاط واخلطها حتى تصبح ناعمة.","اسكب الصلصة فوق المعكرونة ثم أضف ماء المعكرونة المحتفظ به إلى الخلاط الفارغ (لكن غير المغسول). حرّكه جيدًا لجمع أي صلصة متبقية عالقة على جوانب الخلاط. ثم اسكب ذلك فوق المعكرونة أيضًا. قلّب كل شيء جيدًا وقدّم مع مزيد من الفلفل المطحون طازجًا، واستمتع به!"],
[])
R(9373393,"مافن الكوسا النباتي الصحي",
"استمتع بمافن الكوسا النباتي الصحي المثالي للفطور أو الحلوى أو الوجبة الخفيفة.",
"12 قطعة مافن","قطعة مافن واحدة",
["2 كوب دقيق الشوفان، خالٍ من الغلوتين إن أردت","¼ كوب بذور الكتان، كاملة أو مطحونة*","1 ملعقة صغيرة قرفة","¼ ملعقة صغيرة جوزة الطيب","1½ ملعقة صغيرة بيكنج باودر","½ ملعقة صغيرة بيكربونات الصوديوم","⅛ ملعقة صغيرة ملح البحر","½ كوب بيكان أو جوز مفروم، اختياري ولكنه موصى به","2 كوب كوسا مبشورة، أي حوالي حبة كوسا متوسطة","⅓ كوب شراب القيقب","¼ كوب صلصة التفاح غير المحلاة","¾ كوب حليب الصويا"],
["سخّن الفرن مسبقًا على 350° فهرنهايت (175° مئوية) ودهّن صينية المافن.** (انظر الملاحظات إذا كنت تتجنب الزيت)","اعصر الرطوبة الزائدة من الكوسا المبشورة فوق وعاء أو حوض المطبخ. ثم ضعها في وعاء مع بقية المكونات السائلة واخلطها.","اخفق المكونات الجافة في وعاء آخر وأضفها إلى وعاء المكونات السائلة. قلّب حتى لا تتبقى أي كتل دقيق، دون إفراط في الخلط. اترك العجين يرتاح لمدة 10 دقائق، وسيتكاثف قليلًا، ثم قلّبه بسرعة قبل توزيعه على قوالب المافن الاثني عشر.","اخبز لمدة 18-22 دقيقة، أو حتى يخرج عود الأسنان المغروز في الوسط نظيفًا وجافًا. اترك المافن ليبرد في الصينية لمدة 10 دقائق على الأقل، ثم انقله إلى رف سلكي ليواصل التبريد."],
["استخدم بيكنج باودر فعّالًا للحصول على أقصى انتفاخ. فالبيكنج باودر المفتوح في الخزانة لأكثر من 6 أشهر قد يبدأ بفقدان فعاليته.","يمكنك استخدام بذور الكتان كاملة أو مطحونة لهذا المافن. فالبذور الكاملة تضيف قرمشة وقوامًا إضافيين، أما المطحونة فتقدم أقصى فوائد صحية.","يمكنك بشر الكوسا باستخدام مبشرة أو محضّر الطعام، وكلاهما مناسب.","لوصفة خالية من الصويا، استخدم حليب اللوز أو الكاجو.","لوصفة خالية من المكسرات، فقط احذف الجوز أو استخدم رقائق الشوكولاتة أو الفاكهة المجففة لحلاوة إضافية.","اترك العجين يرتاح لمدة 10 دقائق قبل وضعه بالملعقة في صينية المافن للحصول على مافن أكثر هشاشة. قلّبه بسرعة بعد 10 دقائق ثم وزّعه واخبزه.","هذا المافن ليس حلوًا جدًا، لذا إذا كنت تحب الحلويات، فأنصح باستخدام رقائق الشوكولاتة بدلًا من المكسرات المفرومة.","**إذا كانت لديك صينية مافن غير لاصقة جيدة النوعية وجديدة نسبيًا، فلن تحتاج إلى دهنها. جرّبت الطريقتين ولم يلتصق المافن بالصينية. ومع ذلك، يجب أن تنتظر 10 دقائق قبل محاولة نقل المافن إلى رف التبريد. يبقى المافن مغطى في درجة حرارة الغرفة لمدة تصل إلى 3 أيام، وفي الثلاجة لمدة تصل إلى أسبوع، ويُجمَّد في وعاء محكم الإغلاق لمدة تصل إلى 3 أشهر."],
{"Dry Ingredients":"المكونات الجافة","Wet Ingredients":"المكونات السائلة"})
R(9375021,"خبز الموز ورقائق الشوكولاتة النباتي",
"وصفة مضمونة النجاح لخبز موز ورقائق شوكولاتة نباتي طري ولذيذ بإتقان!",
"12 شريحة (رغيف واحد بحجم 5\"×9\")","شريحة واحدة",
["5 حبات موز متوسطة شديدة النضج، أي حوالي 1½ كوب مهروس","⅓ كوب حليب الصويا أو حليب من اختيارك","⅓ كوب صلصة التفاح غير المحلاة","¼ كوب شراب القيقب","2 ملعقة صغيرة مستخلص الفانيليا الطبيعي","½ كوب شوفان مقطع بالفولاذ سريع الطهي أو شوفان مجروش، خالٍ من الغلوتين إن أردت","1½ كوب دقيق القمح الكامل أو دقيق الشوفان لوصفة خالية من الغلوتين، وكلاهما يعطي نتيجة رائعة!","½ ملعقة صغيرة ملح البحر","1 ملعقة صغيرة بيكنج باودر","1 ملعقة صغيرة بيكربونات الصوديوم","¼ كوب رقائق شوكولاتة شبه محلاة وخالية من الألبان"],
["سخّن الفرن مسبقًا على 350 درجة فهرنهايت (175 درجة مئوية) وبطّن قالب رغيف بحجم 5\"×9\" بورق الزبدة.","في وعاء كبير، اهرس الموز وامزجه مع جميع المكونات السائلة. اخلط جيدًا.","أضف المكونات الجافة إلى الوعاء نفسه وقلّب حتى تمتزج فقط، دون إفراط في الخلط. (لا بأس بوجود بعض الكتل الصغيرة!)","اسكب الخليط في قالب الرغيف وسوِّ السطح برفق بملعقة سيليكون. ثم رشّ رقائق الشوكولاتة فوقه (إن استخدمتها) واضغط عليها برفق شديد.","اخبز لمدة 45-55 دقيقة حتى يصبح لونه ذهبيًا فاتحًا ويخرج عود الأسنان المغروز في الوسط نظيفًا. ثم أخرجه من الفرن واتركه ليبرد 10 دقائق قبل إخراج الرغيف من القالب، مستعينًا بورق الزبدة لرفعه. واصل التبريد على رف التبريد لمدة 20-30 دقيقة على الأقل قبل التقطيع."],
["بعد سكب العجين في قالب الرغيف، اطرق القالب برفق عدة مرات على سطح مستوٍ لملء أي فراغات في الخبز. يختلف وقت الطهي بحسب حجم قالب الرغيف، لذا تحقق دائمًا من \"النضج\" بغرز عود أسنان في الوسط لترى إن كان يخرج نظيفًا. احرص على ترك خبز الموز ليرتاح لمدة 30 دقيقة على الأقل ليسهل تقطيعه. تسمح فترة الراحة للخبز بأن يتماسك تمامًا. إذا لم تجد رقائق شوكولاتة خالية من الألبان، فيمكنك استخدام قطع الشوكولاتة، أو خذ أي لوح شوكولاتة نباتية وكسّره إلى قطع بنفسك. لوصفة خالية من الغلوتين، استخدم دقيق شوفان معتمدًا خاليًا من الغلوتين، وإذا لم يكن لديك، فيمكنك طحن شوفان خالٍ من الغلوتين في خلاط أو محضّر طعام حتى تصل إلى قوام الدقيق. ولتكون الوصفة خالية من الصويا، استخدم حليب اللوز أو الكاجو أو أي حليب من اختيارك. إذا لم تكن من محبي الشوكولاتة، فاحذف رقائق الشوكولاتة. أو زيّن الرغيف بشرائح الموز أو الجوز أو البيكان. احفظ المتبقي في درجة حرارة الغرفة لمدة تصل إلى 3 أيام ملفوفًا بإحكام. وفي الثلاجة لمدة تصل إلى أسبوع أو جمّده لمدة تصل إلى 3 أشهر."],
{"Wet Ingredients":"المكونات السائلة","Dry Ingredients":"المكونات الجافة","For Topping (Optional)":"للتزيين (اختياري)"})
R(9376343,"فلفل غير محشي في Instant Pot",
"كل النكهات الرائعة للفلفل المحشي، ولكن أسهل من أي وقت مضى! هذا الفلفل غير المحشي في Instant Pot، المعروف أيضًا بطاجن الفلفل المحشي، مشبع ومريح ولذيذ تمامًا وبكل معنى الكلمة.",
"4 حصص","حصة واحدة",
["1 حبة بصل أصفر مقطعة شرائح","3 فصوص ثوم مفرومة","3 حبات فلفل رومي مقطعة شرائح (من أي لون)","8 أونصات (227 جرامًا) فطر كريميني أو أبيض مقطع شرائح (حوالي 6-8 حبات فطر)","¾ كوب قطع جوز","1 كوب أرز بني غير مطبوخ","1¼ كوب مرق خضار قليل الصوديوم","1 كوب صلصة طماطم أو هريس طماطم من اختيارك","1 ملعقة صغيرة كمون","1½ ملعقة صغيرة مسحوق الفلفل الحار","1½ ملعقة صغيرة بابريكا مدخنة","½ ملعقة صغيرة ملح البحر","¼ ملعقة صغيرة فلفل حار (كايين)، اختياري"],
["شغّل وظيفة التقليب (Sauté) في Instant Pot وأضف بضع ملاعق كبيرة من الماء أو المرق إلى القدر. ضع البصل والثوم والفلفل والفطر والجوز وجميع التوابل بداخله. ثم قلّب لمدة 2-3 دقائق حتى تلين قليلًا.","أضف المكونات المتبقية (المرق وصلصة الطماطم والأرز) وقلّب جيدًا وأغلق الغطاء. ضع الصمام في وضع الإغلاق واطهِ بالضغط لمدة 22 دقيقة. (سيستغرق بناء الضغط حوالي 8 دقائق قبل أن يبدأ القدر بالعد التنازلي.) عند انتهاء المؤقت، اترك الضغط يتحرر طبيعيًا لمدة 10 دقائق. ثم أطلق الضغط المتبقي بسرعة وافتح الغطاء عندما يكون ذلك آمنًا. بالهناء والعافية."],
["لا تقطّع الخضار شرائح رقيقة جدًا. فستُطهى لفترة في القدر، لذا ستتحمل الطهي بشكل أفضل إذا كانت قطعها سميكة. وبدلًا من ذلك، إذا كنت تفضل الخضار مقرمشة، فأخرجها من القدر بعد تقليبها، واطهِ الأرز بالضغط في المرق وصلصة الطماطم، ثم أعد الخضار وقلّب جيدًا. احرص على دفع أي حبات أرز سائبة على جوانب القدر إلى الأسفل قبل الطهي بالضغط. يجب أن يكون كل شيء مغطى بالسائل ليستوي الطهي بالتساوي. إذا كنت قد أطلقت الضغط بالفعل ونسيت تركه يتحرر طبيعيًا لمدة 10 دقائق، فاضغط على وظيفة التقليب وواصل الطهي لمدة 3-5 دقائق مع التقليب المستمر لامتصاص السائل الزائد. أو اتركه جانبًا لحوالي 10 دقائق. سيواصل الأرز امتصاص السائل أثناء راحته وتبريده. يبقى المتبقي صالحًا في الثلاجة لمدة تصل إلى 3 أيام، ويمكنك إعادة تسخينه على الموقد أو في Instant Pot."])
